{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    nodes = case.get("nodes")
    required_symbols = case.get("required_symbols")
    if not isinstance(nodes, list):
        raise ValueError("nodes must be a list")
    if not isinstance(required_symbols, list) or any(not isinstance(x, str) for x in required_symbols):
        raise ValueError("required_symbols must be a list of strings")

    required_fields = ("id", "parent", "symbol", "depth", "removable", "utility")
    by_id = {}
    original_index = {}
    for i, node in enumerate(nodes):
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        for field in required_fields:
            if field not in node:
                raise ValueError("missing node field: " + field)
        if not isinstance(node["id"], str) or node["id"] in by_id:
            raise ValueError("node ids must be unique strings")
        if node["parent"] is not None and not isinstance(node["parent"], str):
            raise ValueError("parent must be null or a string")
        if not isinstance(node["symbol"], str):
            raise ValueError("symbol must be a string")
        if isinstance(node["depth"], bool) or not isinstance(node["depth"], int):
            raise ValueError("depth must be an integer")
        if not isinstance(node["removable"], bool):
            raise ValueError("removable must be boolean")
        if isinstance(node["utility"], bool) or not isinstance(node["utility"], (int, float)):
            raise ValueError("utility must be numeric")
        by_id[node["id"]] = node
        original_index[node["id"]] = i

    for node in nodes:
        parent = node["parent"]
        if parent is not None and parent not in by_id:
            raise ValueError("unknown parent")

    for name in ("grammar_valid", "interestingness_preserved"):
        if name in case and not isinstance(case[name], bool):
            raise ValueError(name + " must be boolean")
    if "registered_candidate_order" in case:
        order = case["registered_candidate_order"]
        if not isinstance(order, list) or any(not isinstance(x, str) for x in order):
            raise ValueError("registered_candidate_order must be a list of strings")
    if "stable_ties" in case and not isinstance(case["stable_ties"], bool):
        raise ValueError("stable_ties must be boolean")

    children = {node["id"]: [] for node in nodes}
    for node in nodes:
        if node["parent"] is not None:
            children[node["parent"]].append(node["id"])

    retained = set(by_id)
    removed = []
    required = set(required_symbols)
    candidates = sorted(nodes, key=lambda n: (-n["depth"], n["id"]))

    def contract_allows(node):
        if case.get("grammar_valid", True) is not True:
            return False
        if case.get("interestingness_preserved", True) is not True:
            return False
        for key in ("grammar_valid", "interestingness_preserved"):
            if key in node and node[key] is not True:
                return False
        return True

    for node in candidates:
        node_id = node["id"]
        if not node["removable"] or node["parent"] is None:
            continue
        if node["symbol"] in required or not contract_allows(node):
            continue
        if any(child in retained for child in children[node_id]):
            continue
        remaining_symbols = {by_id[x]["symbol"] for x in retained if x != node_id}
        if not required.issubset(remaining_symbols):
            continue
        retained.remove(node_id)
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained)
    }
"}
